                    .nav-item-desc {
                        display: none;
                    }

                    .nav-item-head {
                        font-size: 20px;
                    }

                    &:last-child {
                        margin: 0;
                    }
                }

                .current {

                    .arrow {
                        display: none;
                    }

                    .nav-item-head {
                        font-size: 20px;
                        color: $grey;
                    }
                }
            }

            .show {
                transform: translateX(0%);
                position: fixed;
            }

            .hamburger {
                display: block;
            }

            .opened {
                
                .line2 {
                    height: 0;
                    margin: 0;
                }

                .line1 {
                    transform: rotate(45deg);
                    position: absolute;
                }
                .line3 {
                    transform: rotate(-45deg);
                    position: absolute;
                }
            }

            .active {
                transform: translateX(0%);
            }
        }
    }

    footer {

        .footer {
            flex-direction: column;
            padding: 35px 10px;
            text-align: center;

            p {
                margin: 0 auto 10px auto;
                line-height: normal;

                &:last-child {
                    margin: 0 auto;
                }
            }
        }
    }
}

@media screen and (max-width: 481px) {

    footer {

        .footer {
            p,span,a {
                font-size: 14px;
            }
        }
    }
}

