@media screen and (max-width: 961px) {

    main {
        grid-template-columns: 1fr;
        justify-content: center;

        .content {
            margin: 0 auto;
        }
    }

    .sidebar {
        display: none;
    }
}

@media screen and (max-width: 769px) {

    main {

        .content {
            padding-right: 0;

            .about {
                padding-top: 50px;
            }

            .posts {

                .posts-page {

                    .post {

                        .post-content {
                            flex-direction: column;
                            align-items: center;

                            .stats {
                                display: flex;
                                justify-content: space-between;
                                text-align: center;
                                width: 100%;
                                margin-bottom: 25px;

                                div {
                                    margin-bottom: 0;
                                }
                            }

                            .text {
                                align-self: flex-start;
                            }
                        }
                    }
                }

                .pages-indicators {
                    justify-content: center;

                    .pages-indicator {
                        margin-right: 10px;

                        &:last-child {
                            margin-right: 0;
                        }
                    }
                }
            }
        }
    }
}
